head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[checkcombobox > M > getValueArray]<br/>컴포넌트에 선택된 아이템들의 Value 값을 배열로 반환합니다.",
    "validation" : [        
        "컴포넌트에 선택된 아이템 갯수만큼 문자열을 배열로 반환합니다.",        
        "전체 아이템이 선택된 상태여도 allOption 속성으로 추가된 '전체 선택' 아이템은 포함되지 않습니다.",
        "선택된 아이템이 없는 경우 빈 배열을 반환합니다.",
        "반환된 각 객체로 포맷이 적용된 아이템의 Value 값을 갖습니다.",
        "아이템의 Value 값은 <xf:choices> 의 <xf:value> 에 정의된 Value 값을 의미합니다.",        
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
            target1.remove();
    }

    let properties = {
        allOption : true,        
    }

    let cList = $c.gcm.createCList(properties)

    // comp 생성
    $c.gcm.createBasicCheckComboBox(cList);
}



scwin.btn_getValueArray_onclick = function (e) {
    let rtn = target1.getValueArray();
    wf_body_bottom.getObj("scwin").setReturnValue("objArray : " +rtn);

    if (rtn) {
        rtn.forEach(function(item, index) {
            wf_body_bottom.getObj("scwin").setReturnValue("Item index="+index+" 의 value : " +item);            
        });          
    }
};
